+    SynLogInitExceptionIgnore := false;
+    TSynLogInitProbe.Add.Log(sllDebug, 'init');
+    Check(SynLogInitExceptionIgnore, 'no exception log in LogFileInit');
+    Check(not fam.ExceptionIgnoreCurrentThread, 'flags restored');
